const data = $input.first().json;

// Format Risk Distribution
const riskDist = data.risk_distribution.map(d => `<li><b>${d.name}</b>: ${d.value}</li>`).join('');

// Format Department Stats
const deptStats = data.department_risk.map(d => `<li><b>${d.name}</b>: ${d.high_risk_count} candidates</li>`).join('');

// Format Recent Alerts
const recent = data.recent_alerts.slice(0, 5).map(a => `<li>Fit Score: ${a.fit_score} (${a.fit_category}) - ${a.alert_reason || 'N/A'}</li>`).join('');

const message = `
<h3>Weekly HR Analytics Report</h3>
<h4>Risk Distribution</h4>
<ul>${riskDist}</ul>
<h4>Department Breakdown</h4>
<ul>${deptStats}</ul>
<h4>Recent Analysis Activity</h4>
<ul>${recent}</ul>
`;

return [{
  json: {
    subject: "📊 Weekly HR Analytics Report",
    message: message
  }
}];
